  ctx.fillStyle = g; ctx.beginPath(); ctx.moveTo(X(0), h - pad);
  for (let i = 0; i < n; i++) ctx.lineTo(X(i), Y(a[i])); ctx.lineTo(X(n - 1), h - pad); ctx.closePath(); ctx.fill();
  line(a, 'rgba(233,236,239,.92)', 1.6);
