  const fmtDate = (t) => { const y = Math.floor(t), m = Math.min(11, Math.floor((t - y) * 12)); return `${MONTHS[m]} ${y}`; };
  let S = fitCanvas(c), data = null, prog = REDUCED ? 1 : 0, hoverI = -1, started = false;
  addEventListener('resize', () => (S = fitCanvas(c)));
  data = (window.FIG_DATA && window.FIG_DATA.tci) || null;
