  const geo = () => { const { w, h } = S; const l = 54, r = 24, t = 26, b = 36; return { w, h, l, r, t, b, X: (x) => l + (x - X0) / (X1 - X0) * (w - l - r), Y: (y) => t + (Y1 - y) / (Y1 - Y0) * (h - t - b) }; };
