    if (!started) { const r = c.getBoundingClientRect(); if (r.top < innerHeight * 0.85 && r.bottom > 0) started = true; }
    if (started && prog < 1) prog = Math.min(1, prog + dt / 2.8);
    const G = geo(), { ctx, w, h } = S; ctx.clearRect(0, 0, w, h);
    ctx.font = '12.5px JetBrains Mono, monospace';
    // grid
