    ctx.strokeStyle = `rgba(255,184,107,${0.55 * prog})`; ctx.setLineDash([4, 5]);
    ctx.beginPath(); ctx.moveTo(G.l, G.Y(preMean)); ctx.lineTo(w - G.r, G.Y(preMean)); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle = `rgba(255,184,107,${0.85 * prog})`; { const t = `pre-2020 mean ${preMean.toFixed(1)}%`; ctx.fillText(t, w - G.r - ctx.measureText(t).width, G.Y(preMean) + 16); }
    // curve
