    ctx.fillStyle = grad; ctx.beginPath(); ctx.moveTo(G.X(data[0][0]), h - G.b);
    for (let i = 0; i < n; i++) ctx.lineTo(G.X(data[i][0]), G.Y(data[i][1]));
